\section{Introduction}

A \emph{primitive Pythagorean triple} is a triple $(a,b,c)$ of positive integers with
$a^2+b^2=c^2$ and $\gcd(a,b)=1$. Euclid's parameterization states that every such triple
with $a$ odd is uniquely
\[
a=m^2-n^2,\qquad b=2mn,\qquad c=m^2+n^2
\]
for a pair $(m,n)$ with $1\le n<m$, $\gcd(m,n)=1$ and $m+n$ odd.

Barning (1963) and, independently, Hall and later Berggren observed that the primitive
triples form an infinite ternary tree rooted at $(3,4,5)$, with three explicit linear
generators. Price later found a \emph{second}, structurally different ternary tree on the
same set with the same root. Both are complete and non-redundant. We analyse the resulting
configuration exactly, with a specific question in view: does either tree give a handle on
integer factorization?

Factorization enters because the odd leg factors:
\[
a=m^2-n^2=(m-n)(m+n).
\]
A vertex of either tree is not merely a triple; it \emph{is} a factorization. We show that
the natural hope this suggests is exactly and quantifiably false: the trees sort the
factorizations by a coordinate inversely related to factoring difficulty.

\section{The vertex set}

\begin{definition}[Node]
A \emph{node} is a pair $v=(m,n)\in\mathbb Z^2$ with $1\le n$, $n<m$, $\gcd(m,n)=1$ and
$m+n$ odd. We write $\V$ for the set of nodes, $\rt=(2,1)$, and $\sigma(m,n)=m+n$ for the
\emph{size}.
\end{definition}

\begin{definition}[The triple at a node]
For $v=(m,n)$ put $A(v)=m^2-n^2$ (odd leg), $B(v)=2mn$ (even leg), $C(v)=m^2+n^2$
(hypotenuse).
\end{definition}

\begin{proposition}\label{prop:triple}
For every $v$, $A(v)^2+B(v)^2=C(v)^2$. If $v\in\V$ then $A(v)$ is odd and
$\gcd(A(v),B(v))=1$; the triple is primitive.
\end{proposition}

\begin{proof}[Proof sketch]
The Pythagorean identity is a polynomial identity. Since $m+n$ is odd, both $m-n$ and
$m+n$ are odd, so $A=(m-n)(m+n)$ is odd and $\gcd(A,2)=1$. A B\'ezout relation for
$(m,n)$ transforms into explicit B\'ezout certificates for $\gcd(A,m)=1$ and
$\gcd(A,n)=1$; multiplying the three coprimality statements gives $\gcd(A,2mn)=1$.
\end{proof}

\begin{proposition}[Size floor]\label{prop:size}
Every node has $\sigma(v)\ge 3$, with equality iff $v=\rt$.
\end{proposition}

\begin{proof}
$n\ge 1$ and $m>n$ give $m+n\ge 2n+1\ge 3$; equality forces $n=1$, $m=2$.
\end{proof}

\section{An abstract ternary descent framework}

Let $f:\{0,1,2\}\times\V\to\mathbb Z^2$ be three maps. For a word $w=i_1i_2\cdots i_k$ set
$f_w(v)=f_{i_1}(f_{i_2}(\cdots f_{i_k}(v)\cdots))$: the leftmost letter acts last.
Consider the hypotheses
\begin{enumerate}[label=(H\arabic*)]
\item \emph{closure}: $v\in\V\Rightarrow f_i(v)\in\V$;
\item \emph{strict growth}: $v\in\V\Rightarrow \sigma(v)<\sigma(f_i(v))$;
\item \emph{parents exist}: every $v\in\V\setminus\{\rt\}$ is $f_i(u)$ for some $i$ and
some $u\in\V$;
\item \emph{injectivity}: each $f_i$ is injective;
\item \emph{disjointness}: $u,v\in\V$ and $f_i(u)=f_j(v)$ imply $i=j$.
\end{enumerate}

\begin{theorem}[Completeness]\label{thm:complete}
Under \textup{(H1)--(H3)}, every $v\in\V$ equals $f_w(\rt)$ for some word $w$.
\end{theorem}

\begin{proof}[Proof sketch]
Strong induction on $\sigma(v)$, bounded below by $3$ (Proposition~\ref{prop:size}). If
$v=\rt$ take $w=\varepsilon$; otherwise (H3) gives a parent $u$, (H2) gives
$\sigma(u)<\sigma(v)$, and the induction hypothesis applies to $u$.
\end{proof}

\begin{theorem}[Uniqueness]\label{thm:unique}
Under \textup{(H1), (H2), (H4), (H5)}, $f_w(\rt)=f_{w'}(\rt)$ implies $w=w'$.
\end{theorem}

\begin{proof}[Proof sketch]
No $f_i(u)$ with $u\in\V$ equals $\rt$, since by (H2) it has size $>\sigma(u)\ge 3$.
Induct on $|w|$: (H5) forces the leading letters to agree, then (H4) strips them.
\end{proof}

\begin{corollary}[Tree theorem]\label{cor:tree}
Under \textup{(H1)--(H5)}, $w\mapsto f_w(\rt)$ is a bijection from words over $\{0,1,2\}$
onto $\V$; in particular level $L$ has exactly $3^L$ nodes.
\end{corollary}

\section{The two generator triples}

\begin{definition}[Berggren generators]
$\beta_0(m,n)=(2m-n,m)$, $\beta_1(m,n)=(2m+n,m)$, $\beta_2(m,n)=(m+2n,n)$, with matrices
\[
B_0=\begin{pmatrix}2&-1\\1&0\end{pmatrix},\quad
B_1=\begin{pmatrix}2&1\\1&0\end{pmatrix},\quad
B_2=\begin{pmatrix}1&2\\0&1\end{pmatrix},
\]
of determinants $+1,-1,+1$.
\end{definition}

\begin{definition}[Price generators]
$\pi_0(m,n)=(2m,m-n)$, $\pi_1(m,n)=(2m,m+n)$, $\pi_2(m,n)=(m+n,2n)$, with matrices
\[
P_0=\begin{pmatrix}2&0\\1&-1\end{pmatrix},\quad
P_1=\begin{pmatrix}2&0\\1&1\end{pmatrix},\quad
P_2=\begin{pmatrix}1&1\\0&2\end{pmatrix},
\]
of determinants $-2,+2,+2$.
\end{definition}

\begin{theorem}[Closure]\label{thm:closure}
Each $\beta_i$ and each $\pi_i$ maps $\V$ into $\V$.
\end{theorem}

\begin{proof}[Proof sketch]
The inequalities $1\le n'<m'$ are immediate. Parity follows because each matrix has odd
column sums (Theorem~\ref{thm:parity}). Coprimality is the delicate point. For Berggren,
determinant $\pm1$ makes the inverse integral, so B\'ezout coefficients transform
linearly. For Price the determinant is $\pm2$, leaving room for a spurious factor $2$,
and parity closes the gap: e.g.\ for $\pi_1$, $(m',n')=(2m,m+n)$ with $m+n$ odd gives
$\gcd(2,m+n)=1$, while $\gcd(m,m+n)=\gcd(m,n)=1$; multiplying, $\gcd(2m,m+n)=1$.
\end{proof}

\begin{theorem}[Growth]
$\sigma$ strictly increases along every edge: $\beta_0$ and $\pi_0$ add $m-n>0$,
$\beta_1$ and $\pi_1$ add $m+n>0$, $\beta_2$ adds $2n>0$ and $\pi_2$ adds $n>0$.
\end{theorem}

\begin{theorem}[Berggren descent]\label{thm:bparent}
Let $v=(m,n)\in\V$, $v\ne\rt$. Exactly one of the following holds, and each exhibits a
parent in $\V$:
\begin{itemize}
\item $m<2n$: $v=\beta_0(n,\,2n-m)$ \quad (``reflect'');
\item $2n<m<3n$: $v=\beta_1(n,\,m-2n)$ \quad (``reflect and shift'');
\item $m>3n$: $v=\beta_2(m-2n,\,n)$ \quad (``subtract $2n$'').
\end{itemize}
The excluded cases $m=2n$ and $m=3n$ force $n\mid 1$; $m=2n$ then gives the root, and
$m=3n=3$ contradicts parity.
\end{theorem}

\begin{theorem}[Price descent]\label{thm:pparent}
Let $v=(m,n)\in\V$, $v\ne\rt$. If $m=2k$ is even and $n<k$, then $v=\pi_0(k,\,k-n)$; if
$m=2k$ is even and $n>k$, then $v=\pi_1(k,\,n-k)$; if $m$ is odd, so $n=2t$ is even, then
$v=\pi_2(m-t,\,t)$. The excluded case $n=k$ forces $n\mid 1$, i.e.\ the root.
\end{theorem}

The contrast is the heart of the interlock: the Berggren parent rule compares $m$ with
$2n$ and $3n$ --- a subtractive (slow Euclidean, continued-fraction) step on the ratio
$m/n$ --- while the Price parent rule halves $m$ or halves $n$ --- a binary-GCD step on
the sizes.

\begin{theorem}[Injectivity and disjointness]
Each generator is injective. Distinct generators within a family have disjoint images on
$\V$: e.g.\ $\beta_0(u)=\beta_1(u')$ forces $u_1=u_1'$ and $2u_1-u_2=2u_1'+u_2'$, so
$u_2=-u_2'<0$, impossible. The Price cases use the inequalities together with the parity
of $m$.
\end{theorem}

\begin{theorem}[The two tree theorems]\label{thm:trees}
Every node is reached from $(2,1)$ by a unique word of Berggren generators, and by a
unique word of Price generators.
\end{theorem}

\begin{proof}
The preceding theorems verify (H1)--(H5); apply Corollary~\ref{cor:tree}.
\end{proof}

\section{The $N$-node identity}

\begin{definition}[Fermat pair]
For odd $p<q$ set $\Phi(p,q)=\bigl(\tfrac{p+q}{2},\tfrac{q-p}{2}\bigr)$.
\end{definition}

\begin{theorem}[$N$-node identity]\label{thm:nnode}
Let $p,q$ be odd with $1\le p<q$ and $\gcd(p,q)=1$, and let $N=pq$. Then
\begin{enumerate}
\item $\Phi(p,q)\in\V$;
\item the odd leg at $\Phi(p,q)$ is exactly $N$: $A(\Phi(p,q))=pq$;
\item $C(\Phi(p,q))=\tfrac{p^2+q^2}{2}$ and $B(\Phi(p,q))=\tfrac{q^2-p^2}{2}$;
\item writing $\Phi(p,q)=(m,n)$, one recovers $p=m-n$ and $q=m+n$.
\end{enumerate}
\end{theorem}

\begin{proof}
Write $p=2a+1$, $q=2b+1$ with $0\le a<b$; then $\Phi(p,q)=(a+b+1,\,b-a)$, which is
integral, satisfies $1\le b-a<a+b+1$, and has odd coordinate sum $2b+1=q$. A B\'ezout
relation $xp+yq=1$ becomes $(x+y)(a+b+1)+(y-x)(b-a)=1$, giving coprimality. For (2),
\[
A=m^2-n^2=(m-n)(m+n)=(2a+1)(2b+1)=pq .
\]
Items (3) and (4) are the same substitution.
\end{proof}

\begin{theorem}[Bijection]\label{thm:bij}
The maps $(m,n)\mapsto(m-n,m+n)$ and $(p,q)\mapsto\Phi(p,q)$ are mutually inverse
bijections between $\V$ and the set of pairs $(p,q)$ of coprime odd integers with
$1\le p<q$.
\end{theorem}

\begin{proof}
For $(m,n)\in\V$, $m\pm n$ are odd; a common divisor of them divides $2m$ and $2n$ and,
being odd, divides $\gcd(m,n)=1$; and $1\le m-n<m+n$. The composites are the identity by
direct computation.
\end{proof}

\begin{corollary}
Every $N=pq$ as above has a unique address in the Berggren tree and a unique address in
the Price tree, at a node whose odd leg is exactly $N$.
\end{corollary}

\begin{corollary}[Finding a node factors]
If $v=(m,n)\in\V$ and $m-n>1$, then $m-n$ divides $A(v)$ with $1<m-n<A(v)$.
\end{corollary}

\begin{theorem}[Fermat's witness]
With $(m,n)=\Phi(p,q)$ we have $m^2-pq=n^2$. Hence Fermat's method, scanning
$m=\lceil\sqrt N\rceil,\lceil\sqrt N\rceil+1,\dots$ for $m^2-N$ a square, terminates
exactly at the first coordinate of the $N$-node.
\end{theorem}

\begin{example}
$N=391=17\cdot 23$: $\Phi=(20,3)$, triple $(391,120,409)$, and $391=(20-3)(20+3)$.
\end{example}

\section{The interlock: three exact separations}

\begin{theorem}[No conjugacy]\label{thm:noconj}
Let $S$ be a $2\times 2$ integer matrix with $\det S\ne 0$. Then $S B_i\ne P_j S$ for all
$i,j$.
\end{theorem}

\begin{proof}
Taking determinants gives $\det B_i=\det P_j$, impossible since
$\det B_i\in\{\pm 1\}$ and $\det P_j\in\{\pm 2\}$.
\end{proof}

Both trees also act linearly on the triple. In coordinates $(A,B,C)$ the Berggren
generators are the classical Barning--Hall matrices
\[
\mathcal B_0=\begin{pmatrix}1&-2&2\\2&-1&2\\2&-2&3\end{pmatrix},\quad
\mathcal B_1=\begin{pmatrix}1&2&2\\2&1&2\\2&2&3\end{pmatrix},\quad
\mathcal B_2=\begin{pmatrix}-1&2&2\\-2&1&2\\-2&2&3\end{pmatrix},
\]
and the Price generators are
\[
\mathcal P_0=\begin{pmatrix}2&1&1\\2&-2&2\\2&-1&3\end{pmatrix},\quad
\mathcal P_1=\begin{pmatrix}2&-1&1\\2&2&2\\2&1&3\end{pmatrix},\quad
\mathcal P_2=\begin{pmatrix}2&1&-1\\-2&2&2\\-2&1&3\end{pmatrix}.
\]
Let $S$ denote the leg swap $(A,B,C)\mapsto(B,A,C)$.

\begin{theorem}[Berggren is leg-symmetric]
$S\mathcal B_0S=\mathcal B_2$, $S\mathcal B_1S=\mathcal B_1$, $S\mathcal B_2S=\mathcal B_0$.
\end{theorem}

\begin{theorem}[Price is not]
$S\mathcal P_iS\ne\mathcal P_j$ for all $i,j$.
\end{theorem}

\begin{proof}[Proof sketch]
Every Price generator has an even first column; conjugation by the swap pulls an odd
entry into the first column. Explicit computation of the nine products confirms it.
\end{proof}

\begin{theorem}[Interlock rigidity]\label{thm:shared}
If $u\in\V$ and $\beta_i(u)=\pi_j(u)=v$ for some $i,j$, then $v=(3,2)$ or $v=(4,1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Seven of the nine pairs of formulas are impossible on $\V$ (e.g.\ $\beta_0(u)=\pi_0(u)$
requires $u_2=0$). The survivors $\beta_0=\pi_2$ and $\beta_2=\pi_0$ each force
$u_1=2u_2$, which with $\gcd(u_1,u_2)=1$ gives $u_2\mid 1$, i.e.\ $u=\rt$; substituting
gives $(3,2)$ and $(4,1)$ respectively.
\end{proof}

\begin{theorem}[Sharpness]
$\beta_0(\rt)=\pi_2(\rt)=(3,2)$ and $\beta_2(\rt)=\pi_0(\rt)=(4,1)$; the shared-edge set
has exactly two elements.
\end{theorem}

\section{Depth duality}

Write $d_B(v)$ and $d_P(v)$ for the lengths of the unique Berggren and Price addresses.

\begin{theorem}[Price growth bound]\label{thm:pgrow}
For every word $w$, $(\pi_w(\rt))_1\le 2^{|w|+1}$; equivalently $d_P(m,n)\ge\log_2 m-1$.
\end{theorem}

\begin{proof}
Each Price generator at most doubles the first coordinate ($\pi_0,\pi_1: m\mapsto 2m$;
$\pi_2: m\mapsto m+n<2m$). Induct from $m=2$ at the root.
\end{proof}

\begin{theorem}[A level is wider than Fermat's whole scan]\label{thm:level}
If a node at Price depth $d$ has $m\ge 9$, then $m<3^{d}$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:pgrow}, $m^3\le 2^{3d+3}=8\cdot 8^d\le 8\cdot 9^d=8(3^d)^2$. If
$3^d\le m$ then $m^3\le 8m^2$, contradicting $m\ge 9$.
\end{proof}

Since Fermat's scan for the odd leg of that node terminates after
$m-\lfloor\sqrt N\rfloor\le m$ trial values, merely writing down the tree level that
contains the target already costs more than the entire classical scan.

\begin{theorem}[Ratio law]\label{thm:ratio}
For every word $w$, writing $(m,n)=\beta_w(\rt)$ and $d=|w|$, we have $m\le(2d+3)n$.
\end{theorem}

\begin{proof}
Induction on $|w|$; at the root $2\le 3$. Applying $\beta_0$ or $\beta_1$ yields
$(2m\mp n,\,m)$ with ratio $2\mp n/m<3$; applying $\beta_2$ yields $(m+2n,\,n)$ with ratio
$m/n+2\le(2d+3)+2=2(d+1)+3$.
\end{proof}

Since $m/n=(p+q)/(q-p)$ at the $N$-node, Berggren depth is a function of the \emph{ratio}
of the factors, not of the size of $N$.

\begin{theorem}[Exact depth duality]\label{thm:duality}
For every $i\ge 0$ the node $(2^{i+2},1)$ has $d_B=2^{i+1}-1$ and $d_P=i+1$.
\end{theorem}

\begin{proof}[Proof sketch]
$\beta_2^{\,k}(\rt)=(2k+2,1)$ by induction, so $(2^{i+2},1)=\beta_2^{\,2^{i+1}-1}(\rt)$;
uniqueness of addresses makes that word the Berggren address. On the Price side
$\pi_1^{\,i}(\rt)=(2^{i+1},2^{i+1}-1)$, and applying $\pi_0$ gives $(2^{i+2},1)$ with a
word of length $i+1$.
\end{proof}

\section{Orthogonality to factoring}

\begin{theorem}[Berggren depth versus Fermat cost]\label{thm:anti}
For every $k\ge 0$ the node $v_k=(2k+2,1)$ satisfies: its Berggren address is
$\beta_2^{\,k}$, so $d_B(v_k)=k$ exactly; its odd leg is $N_k=(2k+1)(2k+3)$; and Fermat's
scan for $N_k$ succeeds at its first trial value, since with $r=2k+1$ we have
$r^2\le N_k<(r+1)^2$ and the witness is $m=r+1$.
\end{theorem}

So the Berggren tree buries at depth $k$ exactly the factorizations Fermat resolves in one
step.

\begin{lemma}[Fermat's scan length]\label{lem:scan}
Let $N=m^2-n^2$ with $m>0$ and let $r\ge 0$ satisfy $r^2\le N$. Then, with $s=m-r$,
$n^2\le 2ms$.
\end{lemma}

\begin{proof}
$r^2\le m^2-n^2$ gives $r\le m$ and $n^2\le(m-r)(m+r)\le 2m(m-r)$.
\end{proof}

\begin{lemma}[Fermat's cost law]
If $N<(r+1)^2$ and $N=m^2-n^2$, then $(m-r)(m+r)\le n^2+2r$; hence
$s\approx n^2/(2\sqrt N)=(q-p)^2/(8\sqrt N)$.
\end{lemma}

\begin{theorem}[Berggren--Fermat trade-off]\label{thm:tradeoff}
Let $v=\beta_w(\rt)$ with $d=|w|$, $(m,n)=v$, and let $r\ge 0$ satisfy $r^2\le A(v)$;
put $s=m-r$. Then
\[
m\;\le\;2\,s\,(2d+3)^2 .
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:ratio}, $m^2\le(2d+3)^2n^2$; by Lemma~\ref{lem:scan},
$n^2\le 2ms$. Hence $m^2\le 2ms(2d+3)^2$, and divide by $m>0$.
\end{proof}

Rearranged, $d\ge\frac12\bigl(\sqrt{m/(2s)}-3\bigr)$: a cheap Fermat scan forces a
Berggren depth growing like $\sqrt{m/s}$, and that level contains $3^d$ nodes. The two
cost measures are inversely coupled; there is no regime in which the tree is cheap and
Fermat is expensive.

\begin{theorem}[Price is cost-blind]
$m\le 2^{d_P+1}$, with no dependence on $s$: Price depth is a function of size alone and
carries no information about factoring difficulty.
\end{theorem}

\begin{theorem}[Congruence obstruction]\label{thm:mod4}
Let $p$ be a prime with $p\equiv 3\pmod 4$. Then no node $v\in\V$ has $p\mid C(v)$.
\end{theorem}

\begin{proof}
Since $p\equiv 3\pmod 4$, $-1$ is a quadratic non-residue mod $p$. If
$p\mid m^2+n^2=m^2-(-1)n^2$ then $p$ divides both $m$ and $n$, contradicting
$\gcd(m,n)=1$.
\end{proof}

\begin{corollary}
If $N$ has a prime factor $p\equiv 3\pmod 4$ then $N\nmid C(v)$ for every node $v$; in
particular $N=15,21,35,77,91$ never divide a primitive hypotenuse.
\end{corollary}

This is the precise sense in which the odd-leg embedding of Theorem~\ref{thm:nnode} is the
correct one: it is exact and never empty, whereas the hypotenuse embedding is approximate
and sometimes empty.

\section{What a generator triple can look like}

\begin{theorem}[Determinant controls coprimality loss]\label{thm:det}
Let $M=\begin{pmatrix}a&b\\c&d\end{pmatrix}$ be an integer matrix, $(x,y)$ a coprime pair,
and $k$ a common divisor of $ax+by$ and $cx+dy$. Then $k\mid ad-bc$.
\end{theorem}

\begin{proof}
With $ux+vy=1$, we have $(ad-bc)x=d(ax+by)-b(cx+dy)$ and $(ad-bc)y=a(cx+dy)-c(ax+by)$, so
$k$ divides $u(ad-bc)x+v(ad-bc)y=ad-bc$.
\end{proof}

Thus a determinant $\pm1$ generator preserves coprimality unconditionally, while a
determinant $\pm2$ generator does so only via an extra parity argument. The Price tree
occupies exactly this gap.

\begin{theorem}[Parity of column sums]\label{thm:parity}
If an integer matrix $\begin{pmatrix}a&b\\c&d\end{pmatrix}$ sends nodes to nodes, then
$a+c$ and $b+d$ are both odd.
\end{theorem}

\begin{proof}
Applying it to the nodes $(2,1)$ and $(3,2)$ and demanding odd coordinate sums gives
$2(a+c)+(b+d)$ and $3(a+c)+2(b+d)$ odd; reducing mod $2$ gives $b+d\equiv 1$ and then
$a+c\equiv 1$.
\end{proof}

Both generator triples satisfy this, and it rules out naive candidates such as
$(m,n)\mapsto(2m-n,n)$. Theorems~\ref{thm:det} and \ref{thm:parity} are the two constraints
from which any classification of ternary Pythagorean-tree generators must start.

\section{Numerical corroboration}

Systematic computation accompanies the exact statements. Breadth-first search to level
$11$ in both trees confirms completeness and non-redundancy, with parent maps inverting
child maps without failure. For $1020$ random odd semiprimes, the Fermat pair is a valid
node with odd leg exactly $N$ in $1020$ of $1020$ cases. Over $455{,}736$ nodes the two
parent maps agree at exactly $2$ nodes, namely $(3,2)$ and $(4,1)$, matching
Theorem~\ref{thm:shared}. Price depth at the $N$-node is tight and logarithmic,
$\approx 1.4\log_2(p+q)$ with standard deviation $\approx 2.4$ (means $17.7$, $21.4$,
$25.8$, $30.1$ at $14$-, $17$-, $20$-, $23$-bit primes), while Berggren depth is erratic:
at $20$-bit primes, mean $78.5$, range $[19,1135]$, with $\mathrm{corr}(d_B,d_P)=-0.16$.
Over $209$ trials with $20$-bit prime factors, tree traversal (cost $3^{d_B}$) beat
Fermat's scan in $0$ cases: Fermat averaged $6{,}630$ trial values, while the best tree
case was $3^{19}\approx 1.2\times 10^{9}$; moreover
$\mathrm{corr}(d_B,\text{Fermat cost})=-0.31$. Conjugation by the leg swap permutes the
Berggren generators in $3$ of $3$ cases and yields a Price generator in $0$ of $3$.

\section{Discussion}

Four independent structural facts defeat the tree approach to factoring.

First, \emph{level width}: for $m\ge 9$ the tree level containing the $N$-node has more
than $m$ members, while Fermat's whole scan is at most $m$ trials
(Theorem~\ref{thm:level}); unpruned traversal is dominated a priori.

Second, \emph{inverse coupling}: any strategy must traverse a root-to-node path of length
$d_B$, and $m\le 2s(2d+3)^2$ (Theorem~\ref{thm:tradeoff}) says the path is long precisely
when the classical scan is short.

Third, \emph{no local branch rule}: the odd legs along a staircase branch are
$(2k+1)(2k+3)$, carrying no signal that distinguishes the branch containing $N$ from its
siblings; and since the root-to-node word already \emph{is} the factorization, a
polynomial-time predicate recognising its prefixes would itself factor $N$.

Fourth, \emph{wrong sort key}: the trees organise the ratio $(p+q)/(q-p)$ (Berggren) or
the magnitude of $m$ (Price); factoring requires the product $pq$, and the ratio-to-product
map \emph{is} the factorization step.

The Berggren tree is a re-encoding of the slow subtractive Euclidean algorithm on $m/n$;
the Price tree is a re-encoding of the binary GCD on $(m,n)$. Euclidean descent on a known
pair is easy; factoring is the problem of finding the pair. The trees pre-sort all the
answers by exactly the coordinate that is unavailable until the answer is known.

The positive content --- the $N$-node identity, the bijection between nodes and coprime odd
factorizations, and the exact interlock separations --- stands on its own as a clean
description of the geometry of primitive Pythagorean triples.

\section{Future directions}

\begin{conjecture}[Exact Berggren depth]
$d_B(m,n)=\sum_i a_i-(\text{number of ``reflect'' steps})$, where the $a_i$ are the partial
quotients of the subtractive expansion of $m/n$ generated by the three parent rules; in
particular $d_B(m,1)=(m-2)/2$ exactly. The ratio bound $m\le(2d+3)n$ is the crude shadow of
this identity: the Berggren descent \emph{is} the slow Euclidean algorithm, so its depth
must be the sum of the partial quotients, not their number.
\end{conjecture}

\begin{conjecture}[Price depth is $\Theta(\log m)$]
$d_P(m,n)\le 2\log_2 m+O(1)$, which with the proved bound $m\le 2^{d+1}$ gives
$d_P=\Theta(\log m)$, matching the observed $\approx 1.4\log_2(p+q)$. The Price parent
halves $m$ when $m$ is even and halves $n$ when $m$ is odd, and $m$ cannot stay odd on two
consecutive steps once one tracks $(m\bmod 2,\ n\bmod 4)$: the potential $\log_2(mn)$ drops
by at least $1$ per two steps.
\end{conjecture}

\begin{conjecture}[No polynomial-size branch predicate]
There is no predicate $P(N,w)$ computable in time $\mathrm{poly}(\log N,|w|)$ holding
exactly for the prefixes $w$ of the address of the $N$-node of every odd semiprime $N$;
equivalently, the address string is incompressible relative to $N$. Such a predicate would
allow descent to the $N$-node in $O(d)$ evaluations and hence polynomial-time factoring, so
the interest lies in unconditional proofs for restricted predicate classes.
\end{conjecture}

\begin{conjecture}[Classification of ternary generator triples]
Determine all triples of integer matrices generating a complete, non-redundant ternary tree
on $\V$ rooted at $(2,1)$. Theorems~\ref{thm:det} and \ref{thm:parity} are the two starting
constraints; determinants $\pm1$ and $\pm2$ are permitted, and a classification would say
whether Berggren and Price are the only possibilities up to obvious symmetries.
\end{conjecture}

\begin{conjecture}[Beyond the ratio coordinate]
Is there a complete, non-redundant descent on $\V$ whose depth is a function of $pq$ rather
than of $p/q$? A negative answer within the linear-generator class would convert the
empirical barrier into a theorem.
\end{conjecture}

\end{document}

