"""All Fermat decompositions of N, seen as nodes of the two trees.

For an odd N, the coprime factorisations N = p*q with 1 <= p < q are in bijection with the
Euclid pairs (m, n) whose odd leg is exactly N, via

    (p, q) -> ((p+q)/2, (q-p)/2)      and      (m, n) -> (m-n, m+n).

This script, for a list of test values of N:

  * enumerates every coprime factorisation and its node;
  * prints the primitive triple carried by each node, verifying that its odd leg is N;
  * prints both tree addresses of each node and the two depths, showing that Price depth
    tracks log2(m) while Berggren depth tracks the ratio m/n = (p+q)/(q-p);
  * confirms that the tree addresses of distinct factorisations are distinct (each tree
    enumerates the vertex set exactly once, so distinct nodes have distinct addresses);
  * contrasts the traversal cost 3^(Berggren depth) with Fermat's scan length.

Pure standard library.
"""

from __future__ import annotations

import math
from typing import Dict, List, Tuple

Node = Tuple[int, int]
ROOT: Node = (2, 1)


def coprime_factorisations(n_val: int) -> List[Tuple[int, int]]:
    """All pairs (p, q) with p*q = N, gcd(p, q) = 1, 1 <= p < q."""
    out: List[Tuple[int, int]] = []
    d = 1
    while d * d < n_val:
        if n_val % d == 0 and math.gcd(d, n_val // d) == 1:
            out.append((d, n_val // d))
        d += 1
    return out


def fermat_node(p: int, q: int) -> Node:
    return ((p + q) // 2, (q - p) // 2)


def berg_parent(v: Node) -> Tuple[int, Node]:
    m, n = v
    if m < 2 * n:
        return 0, (n, 2 * n - m)
    if m < 3 * n:
        return 1, (n, m - 2 * n)
    return 2, (m - 2 * n, n)


def price_parent(v: Node) -> Tuple[int, Node]:
    m, n = v
    if m % 2 == 0:
        k = m // 2
        return (0, (k, k - n)) if n < k else (1, (k, n - k))
    t = n // 2
    return 2, (m - t, t)


def address(parent, v: Node) -> str:
    letters: List[str] = []
    while v != ROOT:
        i, v = parent(v)
        letters.append("ABC"[i])
    return "".join(letters) or "e"


def fermat_steps(n_val: int) -> int:
    r = math.isqrt(n_val)
    m = r if r * r == n_val else r + 1
    steps = 0
    while True:
        steps += 1
        d = m * m - n_val
        s = math.isqrt(d)
        if s * s == d:
            return steps
        m += 1


def report(n_val: int) -> None:
    facs = coprime_factorisations(n_val)
    print(f"\nN = {n_val}   ({len(facs)} coprime factorisation(s))")
    print("   p       q        node (m,n)      odd leg  even leg  hypotenuse   d_B   d_P"
          "   Berggren address")
    print("  " + "-" * 100)
    seen_b: Dict[str, Node] = {}
    seen_p: Dict[str, Node] = {}
    for p, q in facs:
        v = fermat_node(p, q)
        m, n = v
        wb, wp = address(berg_parent, v), address(price_parent, v)
        assert m * m - n * n == n_val, "odd leg must be exactly N"
        assert wb not in seen_b and wp not in seen_p, "addresses must be distinct"
        seen_b[wb], seen_p[wp] = v, v
        shown = wb if len(wb) <= 28 else wb[:28] + "..."
        print(f"  {p:6d}  {q:6d}   {str(v):>14s}   {m*m-n*n:8d}  {2*m*n:8d}  {m*m+n*n:10d}"
              f"   {len(wb) if wb != 'e' else 0:3d}   {len(wp) if wp != 'e' else 0:3d}   {shown}")
    s = fermat_steps(n_val)
    best = min(len(address(berg_parent, fermat_node(p, q))) for p, q in facs)
    print(f"  Fermat's scan: {s} trial value(s).  Shallowest Berggren address: depth {best}, "
          f"i.e. a level of 3^{best} = {3 ** best:.3e} nodes.")


def main() -> None:
    print(__doc__)
    for n_val in (15, 45, 91, 391, 1155, 3599, 10403):
        report(n_val)
    print("\nIn every case the odd leg at the Fermat pair is exactly N, the two addresses are")
    print("unique, and the tree level needed to reach the node dwarfs Fermat's own scan.")


if __name__ == "__main__":
    main()

