"""Berggren address descent: the subtractive (continued-fraction) parent rule."""

from __future__ import annotations

import math
from typing import List, Tuple

Node = Tuple[int, int]
ROOT: Node = (2, 1)


def is_node(v: Node) -> bool:
    """Valid Euclid parameters: 1 <= n < m, gcd(m, n) = 1, m + n odd."""
    m, n = v
    return 1 <= n < m and math.gcd(m, n) == 1 and (m + n) % 2 == 1


def berg_child(i: int, v: Node) -> Node:
    """Berggren children, matrices of determinant +1, -1, +1."""
    m, n = v
    return [(2 * m - n, m), (2 * m + n, m), (m + 2 * n, n)][i]


def berg_parent(v: Node) -> Tuple[int, Node]:
    """The unique Berggren parent of a non-root node, with the letter that produced it.

    Compares m against 2n and 3n:
      m < 2n      -> reflect:            v = child_0(n, 2n - m)
      2n < m < 3n -> reflect and shift:  v = child_1(n, m - 2n)
      m > 3n      -> subtract 2n:        v = child_2(m - 2n, n)
    The excluded cases m = 2n, m = 3n force n = 1 and reduce to the root or violate parity.
    """
    m, n = v
    if v == ROOT:
        raise ValueError("the root has no parent")
    if m < 2 * n:
        return 0, (n, 2 * n - m)
    if m < 3 * n:
        return 1, (n, m - 2 * n)
    return 2, (m - 2 * n, n)


def berg_address(v: Node) -> List[int]:
    """The unique root-to-node Berggren word, leftmost letter acting last."""
    if not is_node(v):
        raise ValueError(f"{v} is not a valid Euclid pair")
    letters: List[int] = []
    while v != ROOT:
        i, v = berg_parent(v)
        letters.append(i)
    return letters


def berg_replay(word: List[int]) -> Node:
    """Reconstruct the node from its address, verifying the descent."""
    v = ROOT
    for i in reversed(word):
        v = berg_child(i, v)
    return v


if __name__ == "__main__":
    for v in [(4, 1), (20, 3), (55, 42), (1024, 1)]:
        w = berg_address(v)
        assert berg_replay(w) == v
        m, n = v
        d = len(w)
        print(f"node {v}: depth {d}, ratio m/n = {m/n:8.3f} <= 2d+3 = {2*d+3}, "
              f"odd leg {m*m - n*n} = {m-n} * {m+n}")
